"""Plot the H2/CO reaction-balance check generated by make -C test co."""

import argparse
from pathlib import Path

import matplotlib

if __name__ == "__main__":
    matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np

from plot_style import BLUE, GRAY, GREEN, ORANGE, PLOT_STYLE, PURPLE, SKY


PLOT_DIR = Path(__file__).resolve().parent
BALANCE_LIMIT = 1.0e-6   # Same limits as test/MolecularTest.c.
TEMPERATURE_COLORS = {30.0: BLUE, 100.0: GREEN, 300.0: ORANGE, 1000.0: PURPLE}
ILLUMINATION_LABELS = {-np.inf: "No ionizing flux", -5.0: r"$\log_{10} U=-5$", -3.0: r"$\log_{10} U=-3$"}
BALANCES = (
    ("residual_H2", r"H$_2$ formation / destruction", BLUE),
    ("residual_CO", "CO formation / destruction", ORANGE),
    ("residual_H", "H ionization (with charge transfer)", GREEN),
    ("CO_consistency", r"CO re-solved from final H$_2$", PURPLE),
)


def load_csv(path):
    data = np.genfromtxt(path, names=True, delimiter=",", dtype=None, encoding="utf-8", ndmin=1)
    if not data.size:
        raise ValueError(f"No data in {path}")
    return data


def load_results(data_dir):
    return load_csv(data_dir / "equilibrium.csv"), load_csv(data_dir / "column_scan.csv")


def illumination_values(data):
    values = np.unique(data["log_U"])
    return [-np.inf] + sorted(v for v in values if np.isfinite(v))


def plot_abundances(grid):
    """Molecular fractions across density for each temperature and ionizing flux."""
    columns = illumination_values(grid)
    fig, axes = plt.subplots(2, len(columns), figsize=(11, 6), sharex=True, sharey="row", layout="constrained")
    fig.suptitle(r"Equilibrium molecular fractions · $G_0=1.7$, "
                 r"$N_{\rm H}=2\times10^{21}(n_{\rm H}/100)^{1/2}$ cm$^{-2}$")
    for col, log_u in enumerate(columns):
        at_flux = grid[np.isneginf(grid["log_U"])] if np.isneginf(log_u) else grid[grid["log_U"] == log_u]
        for temperature, color in TEMPERATURE_COLORS.items():
            rows = np.sort(at_flux[at_flux["T"] == temperature], order="nH")
            label = rf"$T={temperature:g}$ K"
            axes[0, col].plot(rows["nH"], rows["H2"], color=color, label=label)
            axes[1, col].plot(rows["nH"], rows["CO"], color=color, label=label)
        axes[0, col].set_title(ILLUMINATION_LABELS.get(log_u, rf"$\log_{{10}} U={log_u:g}$"))
        axes[1, col].set_xlabel(r"$n_{\rm H}$ [cm$^{-3}$]")
    for ax in axes.flat:
        ax.set(xscale="log", yscale="log", ylim=(1e-8, 2))
    axes[0, 0].set_ylabel(r"$2n_{\rm H_2}/n_{\rm H}$")
    axes[1, 0].set_ylabel(r"$n_{\rm CO}/n_{\rm C}$")
    axes[0, 0].legend(loc="lower right", fontsize=8)
    return fig


def plot_column_scan(scan):
    """H/H2 and C+/C/CO transitions with visual extinction."""
    cases = sorted({(row["nH"], row["G0"]) for row in scan})
    fig, axes = plt.subplots(2, len(cases), figsize=(11, 5.8), sharex=True, sharey="row", layout="constrained")
    fig.suptitle(r"Column scan without ionizing flux · $T=30$ K")
    for col, (density, field) in enumerate(cases):
        rows = np.sort(scan[(scan["nH"] == density) & (scan["G0"] == field)], order="Nt")
        av = rows["Av"]
        hydrogen, carbon = axes[0, col], axes[1, col]
        hydrogen.plot(av, rows["HI"], color=GRAY, label="H I")
        hydrogen.plot(av, rows["H2"], color=BLUE, label=r"H$_2$ ($2n_{\rm H_2}/n_{\rm H}$)")
        hydrogen.plot(av, rows["HII"], color=ORANGE, ls="--", label="H II")
        carbon.plot(av, rows["CII"], color=ORANGE, label="C II")
        carbon.plot(av, rows["CI"], color=GREEN, label="C I")
        carbon.plot(av, rows["CO"], color=PURPLE, label="CO")
        hydrogen.set_title(rf"$n_{{\rm H}}={density:g}$, $G_0={field:g}$", fontsize=10)
        carbon.set_xlabel(r"$A_V$ [mag]")
    for ax in axes.flat:
        ax.set(xscale="log", yscale="log", ylim=(1e-6, 2))
    axes[0, 0].set_ylabel("Hydrogen fraction")
    axes[1, 0].set_ylabel("Carbon fraction")
    axes[0, 0].legend(loc="lower left", fontsize=8)
    axes[1, 0].legend(loc="lower left", fontsize=8)
    return fig


def plot_balances(grid, scan):
    """Relative residual of each reaction balance; the dashed line is the test limit."""
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.2), sharey=True, layout="constrained")
    fig.suptitle("Reaction balances in the returned equilibria")
    floor = 1e-18
    panels = ((axes[0], grid, "nH", r"$n_{\rm H}$ [cm$^{-3}$]", "Density grid"),
              (axes[1], scan, "Av", r"$A_V$ [mag]", "Column scan"))
    for ax, data, x, xlabel, title in panels:
        for (field, label, color), marker in zip(BALANCES, ("o", "s", "^", "D")):
            ax.scatter(data[x], np.maximum(data[field], floor), s=10, color=color, marker=marker,
                       alpha=0.65, label=label)
        ax.axhline(BALANCE_LIMIT, color=GRAY, ls="--", lw=1, label="Test limit")
        ax.set(xscale="log", yscale="log", ylim=(floor/3, 1), xlabel=xlabel, title=title)
    axes[0].set_ylabel(r"Relative residual  $|F_+-F_-|/\max(F_+,F_-)$")
    axes[1].legend(loc="upper right", fontsize=8)
    fig.text(0.5, -0.02, f"Values below {floor:g} are drawn at {floor:g}.", ha="center", fontsize=8)
    return fig


def plot_fluxes(grid, temperature=30.0):
    """H2 and CO formation and destruction fluxes across density."""
    rows = np.sort(grid[(grid["T"] == temperature) & np.isneginf(grid["log_U"])], order="nH")
    density_squared = rows["nH"]**2
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.2), layout="constrained")
    fig.suptitle(rf"Formation and destruction · $T={temperature:g}$ K, no ionizing flux")
    terms = (
        (axes[0], r"H$_2$", (("H2_formation", "Grain formation", BLUE, "-"),
                            ("H2_photodissociation", "Photodissociation", ORANGE, "--"),
                            ("H2_collisional_dissociation", "Collisional dissociation", PURPLE, ":"))),
        (axes[1], "CO", (("CO_formation", r"Formation (C$^+$ + H$_2$)", BLUE, "-"),
                         ("CO_photodissociation", "Photodissociation", ORANGE, "--"))),
    )
    for ax, title, series in terms:
        for field, label, color, style in series:
            ax.plot(rows["nH"], np.ma.masked_less_equal(rows[field] / density_squared, 0),
                    color=color, ls=style, label=label)
        ax.set(xscale="log", yscale="log", title=title, xlabel=r"$n_{\rm H}$ [cm$^{-3}$]")
        ax.legend(loc="lower left", fontsize=8)
    axes[0].set_ylabel(r"Flux / $n_{\rm H}^2$ [cm$^3$ s$^{-1}$]")
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", type=Path, default=PLOT_DIR.parent / "test" / "out" / "co")
    parser.add_argument("--output-dir", type=Path, default=PLOT_DIR / "out" / "co")
    args = parser.parse_args()
    try:
        grid, scan = load_results(args.data_dir)
    except (OSError, ValueError) as error:
        parser.error(str(error))

    args.output_dir.mkdir(parents=True, exist_ok=True)
    with plt.rc_context(PLOT_STYLE):
        figures = {
            "molecular_fractions.png": plot_abundances(grid),
            "column_scan.png": plot_column_scan(scan),
            "reaction_balances.png": plot_balances(grid, scan),
            "formation_destruction.png": plot_fluxes(grid),
        }
        for name, fig in figures.items():
            fig.savefig(args.output_dir / name, dpi=180, bbox_inches="tight")
            plt.close(fig)
    print(f"Molecular chemistry plots written to {args.output_dir}")


if __name__ == "__main__":
    main()
